
ON CONFLICT DO NOTHING;

ON CONFLICT (slug) DO NOTHING;

ON CONFLICT (slug) DO NOTHING;

SELECT 'dc_project', p.id, 'record', NULL,
       p.name || ' - ' || p.status || ' (' || p.status_publication || ')',
       CASE WHEN p.status_publication = 'published'
            THEN 'New project record added and published; primary source from the planning or permitting authority verified.'
            ELSE 'New project record added as a private draft; evidence insufficient for publication.' END,
       'Editorial team', 'v1.0', true
FROM public.dc_projects p
WHERE p.created_at > now() - interval '5 minutes';
